   [28]={next_id=29, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这里有我的“家人”在等我。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 1, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 1,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
